"use client";

import { createContext, useContext, useState, useEffect, useMemo, ReactNode } from "react";
import { useRouter } from "next/navigation";

interface AuthContextType {
  isAuthenticated: boolean;
  shopId: string;
  login: (email: string, password: string) => Promise<void>;
  logout: () => void;
  isLoading: boolean;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export function AuthProvider({ children }: { children: ReactNode }) {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const router = useRouter();

  // shopIdを取得（認証情報から取得、またはデフォルト値を使用）
  // TODO: 実際の認証実装では、ユーザー情報からshopIdを取得
  const shopId = useMemo(() => {
    if (typeof window === "undefined") return "default_shop";
    const storedShopId = localStorage.getItem("shopId");
    return storedShopId || "default_shop";
  }, []);

  useEffect(() => {
    // ローカルストレージから認証状態を復元
    const authStatus = localStorage.getItem("isAuthenticated");
    if (authStatus === "true") {
      setIsAuthenticated(true);
    }
    setIsLoading(false);
  }, []);

  const login = async (email: string, password: string) => {
    // フロントのみのため、実際の認証処理は実装しない
    // 実際の実装では、ここでAPIを呼び出す
    await new Promise((resolve) => setTimeout(resolve, 1000));
    
    // 認証成功として扱う
    setIsAuthenticated(true);
    localStorage.setItem("isAuthenticated", "true");
    router.push("/");
  };

  const logout = () => {
    setIsAuthenticated(false);
    localStorage.removeItem("isAuthenticated");
    router.push("/login");
  };

  return (
    <AuthContext.Provider value={{ isAuthenticated, shopId, login, logout, isLoading }}>
      {children}
    </AuthContext.Provider>
  );
}

export function useAuth() {
  const context = useContext(AuthContext);
  if (context === undefined) {
    throw new Error("useAuth must be used within an AuthProvider");
  }
  return context;
}
